import { Component, Prop, h } from '@stencil/core';

// Component ui-box: Deprecated
@Component({
  tag: 'ui-box',
  styleUrl: 'ui-box.css',
  shadow: true
})
export class UiBoxComponent {
  @Prop() classes: string;
  @Prop() label: string;
  @Prop() labelLink: string;
  @Prop() iconLink: string;
  @Prop() link: boolean;
  @Prop() classesLink: string;

  render() {
    const boxClasses = ['rounded-lg flex flex-col gap-5 p-6 border border-alternative-medium lg:flex-1', this.classes].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class={boxClasses}>
        <div class="flex items-center justify-between">
          <h3 class="relative after:content-[''] after:absolute after:-bottom-2 after:left-0 after:w-6 after:h-[2px] after:bg-primary text-dark text-lg font-bold flex items-center gap-2">
            {this.label}
          </h3>
          {this.link && <std-link label={this.labelLink} icon={this.iconLink} icon-position="left" classes={this.classesLink}></std-link>}
        </div>
        <div>
          <slot />
        </div>
      </div>
    );
  }
}
